update public.question_solution_steps set title='Analise os distratores', content_markdown='“$11110000_2+00001000_2$” não cumpre o critério técnico do caso: $112+48=160$ excede o máximo $127$. “$00000101_2+11111011_2$” não decorre do princípio aplicável: Overflow ocorre ao somar dois números de mesmo sinal e obter sinal oposto. “$10000000_2+00000000_2$” deixa de executar a análise necessária: Observe os bits de sinal antes e depois da soma.', sort_order=4 where id='70000000-0000-4000-8000-000009300304';
