update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de little-endian: Em little-endian, o que significa o endereço do primeiro byte de uma palavra?', sort_order=1 where id='70000000-0000-4000-8000-000009300471';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='A convenção define a ordem dos bytes na memória.', sort_order=2 where id='70000000-0000-4000-8000-000009300472';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Associe “menor endereço” a “menor significância”. No enunciado, Em little-endian, o que significa o endereço do primeiro byte de uma palavra? A palavra mantém valor lógico; só muda a disposição física.', sort_order=3 where id='70000000-0000-4000-8000-000009300473';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Ele sempre contém o byte mais significativo.” não cumpre o critério técnico do caso: A palavra mantém valor lógico; só muda a disposição física. “Ele contém o opcode.” não decorre do princípio aplicável: A convenção define a ordem dos bytes na memória. “Ele não armazena dados.” deixa de executar a análise necessária: Associe “menor endereço” a “menor significância”.', sort_order=4 where id='70000000-0000-4000-8000-000009300474';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Ele contém o byte menos significativo.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300475';

update public.question_solutions set final_answer_markdown='$0,101_2$', explanation_markdown='Frações binárias usam pesos $1/2$, $1/4$, $1/8$ e assim por diante. No caso apresentado, Decomponha $0,625=1/2+1/8$. Os bits nas posições $1/2$ e $1/8$ são $1$. Logo, “$0,101_2$” é a conclusão correta. “$0,110_2$” não cumpre o critério técnico do caso: Os bits nas posições $1/2$ e $1/8$ são $1$. “$0,011_2$” não decorre do princípio aplicável: Frações binárias usam pesos $1/2$, $1/4$, $1/8$ e assim por diante. “$0,100_2$” deixa de executar a análise necessária: Decomponha $0,625=1/2+1/8$.' where question_id='40000000-0000-4000-8000-000000930048';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de conversão de base: Qual é $0,625_{10}$ em binário?', sort_order=1 where id='70000000-0000-4000-8000-000009300481';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='Frações binárias usam pesos $1/2$, $1/4$, $1/8$ e assim por diante.', sort_order=2 where id='70000000-0000-4000-8000-000009300482';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Decomponha $0,625=1/2+1/8$. No enunciado, Qual é $0,625_{10}$ em binário? Os bits nas posições $1/2$ e $1/8$ são $1$.', sort_order=3 where id='70000000-0000-4000-8000-000009300483';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“$0,110_2$” não cumpre o critério técnico do caso: Os bits nas posições $1/2$ e $1/8$ são $1$. “$0,011_2$” não decorre do princípio aplicável: Frações binárias usam pesos $1/2$, $1/4$, $1/8$ e assim por diante. “$0,100_2$” deixa de executar a análise necessária: Decomponha $0,625=1/2+1/8$.', sort_order=4 where id='70000000-0000-4000-8000-000009300484';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “$0,101_2$”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300485';

update public.question_solutions set final_answer_markdown='Multiplicar o valor por $2$.', explanation_markdown='Um shift lógico à esquerda desloca cada peso para a próxima potência de dois. No caso apresentado, Compare os pesos antes e depois do deslocamento. Cada contribuição dobra, se nenhum bit significativo for perdido. Logo, “Multiplicar o valor por $2$.” é a conclusão correta. “Dividir o valor por $2$.” não cumpre o critério técnico do caso: Cada contribuição dobra, se nenhum bit significativo for perdido. “Inverter todos os bits.” não decorre do princípio aplicável: Um shift lógico à esquerda desloca cada peso para a próxima potência de dois. “Adicionar sempre $1$.” deixa de executar a análise necessária: Compare os pesos antes e depois do deslocamento.' where question_id='40000000-0000-4000-8000-000000930049';
