update public.question_solution_steps set title='Recupere o princípio', content_markdown='Um shift lógico à esquerda desloca cada peso para a próxima potência de dois.', sort_order=2 where id='70000000-0000-4000-8000-000009300492';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Compare os pesos antes e depois do deslocamento. No enunciado, Para um inteiro sem sinal sem overflow, deslocar $00101101_2$ uma posição à esquerda equivale a: Cada contribuição dobra, se nenhum bit significativo for perdido.', sort_order=3 where id='70000000-0000-4000-8000-000009300493';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Dividir o valor por $2$.” não cumpre o critério técnico do caso: Cada contribuição dobra, se nenhum bit significativo for perdido. “Inverter todos os bits.” não decorre do princípio aplicável: Um shift lógico à esquerda desloca cada peso para a próxima potência de dois. “Adicionar sempre $1$.” deixa de executar a análise necessária: Compare os pesos antes e depois do deslocamento.', sort_order=4 where id='70000000-0000-4000-8000-000009300494';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Multiplicar o valor por $2$.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300495';

update public.question_solutions set final_answer_markdown='Reduzir o erro relativo de arredondamento para valores representáveis.', explanation_markdown='Precisão está ligada aos bits do significando; faixa está ligada principalmente ao expoente. No caso apresentado, Diferencie quantos dígitos são preservados de quão grande o número pode ser. Mais precisão reduz, mas não elimina, erros de representação. Logo, “Reduzir o erro relativo de arredondamento para valores representáveis.” é a conclusão correta. “Aumentar apenas o maior expoente.” não cumpre o critério técnico do caso: Mais precisão reduz, mas não elimina, erros de representação. “Eliminar a necessidade de sinal.” não decorre do princípio aplicável: Precisão está ligada aos bits do significando; faixa está ligada principalmente ao expoente. “Tornar todas as frações exatas.” deixa de executar a análise necessária: Diferencie quantos dígitos são preservados de quão grande o número pode ser.' where question_id='40000000-0000-4000-8000-000000930050';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de precisão: Qual é a melhor explicação para usar mais bits no significando de um formato de ponto flutuante?', sort_order=1 where id='70000000-0000-4000-8000-000009300501';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='Precisão está ligada aos bits do significando; faixa está ligada principalmente ao expoente.', sort_order=2 where id='70000000-0000-4000-8000-000009300502';
