update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Reduzir o erro relativo de arredondamento para valores representáveis.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300505';

